{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_18762b623260e81312674658", "claim_ids": ["claim_163df575e5b1b27bb1497884", "claim_facd8b598d9d8b7ed160f900"], "query_ids": ["q_308"], "claims": [{"claim_id": "claim_163df575e5b1b27bb1497884", "quote": "Import adjustment offset amounts will be calculated as follows: • 3.75% of aggregate MSRP for eligible autos assembled between April 3, 2025, and April 30, 2026", "url": "https://www.trade.gov/press-release/department-commerce-announces-new-auto-tariff-offset-process", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {}}, {"claim_id": "claim_facd8b598d9d8b7ed160f900", "quote": "Approved import adjustment offset amounts are valid until fully used, provided they were granted based on qualifying autos assembled in the United States between April 3, 2025 and April 30, 2027.", "url": "https://www.trade.gov/press-release/department-commerce-announces-new-auto-tariff-offset-process", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {}}]}, {"pair_id": "conflict_004c2d1931e8a189cf629bc7", "claim_ids": ["claim_412020137629721ca450ce54", "claim_aae340ff52f3a36cdc438396"], "query_ids": ["q_308"], "claims": [{"claim_id": "claim_412020137629721ca450ce54", "quote": "Only auto parts for passenger vehicles and light trucks, as defined by Executive Order 14257, issued April 2, 2025, and subject to Section 232 duties as of May 3, 2025, are not subject to the reciprocal duties effective April 5, 2025, pursuant to heading 9903.01.33, HTSUS.", "url": "https://www.cbp.gov/trade/programs-administration/entry-summary/section-232-additional-faqs-autos", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "Section 232 duties", "affected_product": "auto parts for passenger vehicles and light trucks", "hts_code": "9903.01.33, HTSUS", "effective_date": "May 3, 2025"}}, {"claim_id": "claim_aae340ff52f3a36cdc438396", "quote": "Pursuant to President Donald J. Trump’s proclamation on March 26, 2025, 25% tariffs on imports of automobile parts went into effect on May 3, 2025.", "url": "https://www.trade.gov/press-release/department-commerce-announces-new-auto-tariff-offset-process", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "Section 232 tariffs", "duty_rate": "25%", "effective_date": "May 3, 2025"}}]}, {"pair_id": "conflict_2d0aea24f7f9fbe8f4c8a07a", "claim_ids": ["claim_1842022f5f33c482a7ba2b4b", "claim_da2dcab1571a982f3f3e9028"], "query_ids": ["q_309"], "claims": [{"claim_id": "claim_1842022f5f33c482a7ba2b4b", "quote": "for automobile parts, the tariffs will start collection on May 3, 2025 (with a carveout for USMCA-certified parts, which will be exempt until a collection mechanism is finalized).", "url": "https://www.foley.com/insights/publications/2025/04/auto-sector-company-new-automotive-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"effective_date": "May 3, 2025"}}, {"claim_id": "claim_da2dcab1571a982f3f3e9028", "quote": "The auto parts tariffs begin on May 3, 2025, but USMCA-compliant parts are exempt until the Secretary of Commerce, in consultation with CBP, establishes a process to apply tariffs to non-U.S. content.", "url": "https://www.foley.com/insights/publications/2025/04/auto-sector-company-new-automotive-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"effective_date": "May 3, 2025"}}]}, {"pair_id": "conflict_483eff3ef75aacce5ba105b2", "claim_ids": ["claim_397c612ad8d3b9e56cbc0b1f", "claim_8fb303c3a80d87e7b05018bd"], "query_ids": ["q_309"], "claims": [{"claim_id": "claim_397c612ad8d3b9e56cbc0b1f", "quote": "The duty provided in the applicable subheading + a duty of 25% upon the value of the non-U.S. content", "url": "https://public-inspection.federalregister.gov/2025-05930.pdf", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "9903.94.03", "duty_rate": "25%", "effective_date": "April 3, 2025"}}, {"claim_id": "claim_8fb303c3a80d87e7b05018bd", "quote": "The duty provided in the applicable subheading + a duty of 25% upon the value of the non-U.S. content", "url": "https://public-inspection.federalregister.gov/2025-05930.pdf", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "9903.94.03", "duty_rate": "25%"}}]}, {"pair_id": "conflict_a66107bd632ae77e2c4170f8", "claim_ids": ["claim_e4f93b1e38d5f159ee3d1540", "claim_fb242165b023dbe88ae4a2fb"], "query_ids": ["q_309"], "claims": [{"claim_id": "claim_e4f93b1e38d5f159ee3d1540", "quote": "established comprehensive 25% tariffs on imported automobiles (sedans, sport utility vehicles, crossover vehicles, minivans, and cargo vans) as well as light trucks.", "url": "https://www.foley.com/insights/publications/2025/04/auto-sector-company-new-automotive-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "25%", "effective_date": "April 3, 2025"}}, {"claim_id": "claim_fb242165b023dbe88ae4a2fb", "quote": "The duty provided in the applicable subheading + 25%", "url": "https://public-inspection.federalregister.gov/2025-05930.pdf", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "9903.94.01", "duty_rate": "25%", "effective_date": "April 3, 2025"}}]}, {"pair_id": "conflict_93939c4fe7835d379de24281", "claim_ids": ["claim_241d5d48cb8b4065fe9d233f", "claim_5509a54ae49555736ba15d98"], "query_ids": ["q_31"], "claims": [{"claim_id": "claim_241d5d48cb8b4065fe9d233f", "quote": "Because definitely all the cars that we would produce here are going to be exempted from any tariffs,” said Hyundai Motor Company CEO Jose Munoz.", "url": "https://www.teslarati.com/hyundai-georgia-plant-vs-trump-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai Motor Company", "tariff_program": "any tariffs"}}, {"claim_id": "claim_5509a54ae49555736ba15d98", "quote": "Hyundai’s $7.6 billion Georgia plant dodged U.S. President Donald Trump’s recently announced tariffs on imported vehicles and auto parts.", "url": "https://www.teslarati.com/hyundai-georgia-plant-vs-trump-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai Motor Group Metaplant America", "tariff_program": "U.S. President Donald Trump’s recently announced tariffs on imported vehicles and auto parts", "duty_rate": "25%"}}]}, {"pair_id": "conflict_7d242bb9f6f036c3f721dc4c", "claim_ids": ["claim_241d5d48cb8b4065fe9d233f", "claim_e9b23f6a44d0a10ce9ce4d68"], "query_ids": ["q_31"], "claims": [{"claim_id": "claim_241d5d48cb8b4065fe9d233f", "quote": "Because definitely all the cars that we would produce here are going to be exempted from any tariffs,” said Hyundai Motor Company CEO Jose Munoz.", "url": "https://www.teslarati.com/hyundai-georgia-plant-vs-trump-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai Motor Company", "tariff_program": "any tariffs"}}, {"claim_id": "claim_e9b23f6a44d0a10ce9ce4d68", "quote": "Hyundai has announced that it won't raise prices on its current lineup of new cars for at least two months. This comes a day after the Korean automaker confirmed that it will no longer offer free complimentary maintenance on 2026-and-new models. Called the \"Customer Assurance\" program, it's a direct response to the new U.S. tariffs, and Hyundai says it will be in place until June 2.", "url": "https://www.caranddriver.com/news/a64375899/automakers-trump-tariff-response", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai", "tariff_program": "Customer Assurance", "effective_date": "June 2"}}]}, {"pair_id": "conflict_04160343f404508cb32f2708", "claim_ids": ["claim_1d21e400d3f8c64ba5dde38f", "claim_1f9dc6f9dcf2b8e8e0691886"], "query_ids": ["q_310"], "claims": [{"claim_id": "claim_1d21e400d3f8c64ba5dde38f", "quote": "Specifically, these credits will be available to OEMs in an amount equal to 3.75 percent of the aggregate Manufacturer’s Suggested Retail Price (MSRP) value of all in-scope automobiles assembled in the United States by that", "url": "https://www.thompsonhinesmartrade.com/2025/04/white-house-amends-automobile-parts-tariffs-to-ease-burden-on-u-s-automakers", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}, {"claim_id": "claim_1f9dc6f9dcf2b8e8e0691886", "quote": "OEMs will be eligible to receive 2.5 percent of the aggregate MSRP value. These percentages reflect the total duty that would be owed when a 25 percent duty is applied to parts accounting 15% (2025-26) and 10% (2026-27) of the automobile’s MSRP value, respectively.", "url": "https://www.thompsonhinesmartrade.com/2025/04/white-house-amends-automobile-parts-tariffs-to-ease-burden-on-u-s-automakers", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "section 232 duties for automobile parts", "duty_rate": "25 percent", "effective_date": "April 3, 2025", "expiration_date": "April 30, 2026"}}]}, {"pair_id": "conflict_9541680d944ebce0c170fbfd", "claim_ids": ["claim_64a0be9681d4336ef878872f", "claim_9039d913db542b25c47e6ea0"], "query_ids": ["q_310"], "claims": [{"claim_id": "claim_64a0be9681d4336ef878872f", "quote": "To offset the parts tariffs paid by an OEM over a two-year transition period, vehicles assembled in the United States between April 3, 2025, and April 30, 2026, may qualify for an import part tariff adjustment offset of 3.75% of the total Manufacturers Suggested Retail Price (MSRP) value.", "url": "https://www.plantemoran.com/explore-our-thinking/insight/2025/05/adjusting-automobile-and-automobile-parts-tariffs-action", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "import part tariff adjustment offset", "duty_rate": "3.75%", "effective_date": "April 3, 2025", "expiration_date": "April 30, 2026"}}, {"claim_id": "claim_9039d913db542b25c47e6ea0", "quote": "The automobile manufacturer may apply for an import adjustment offset amount equal to 2.5 percent of the aggregate MSRP value of all automobiles assembled in the United States from May 1, 2026, through April 30, 2027.", "url": "https://www.whitehouse.gov/presidential-actions/2025/04/amendments-to-adjusting-imports-of-automobiles-and-automobile-parts-into-the-united-states", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"duty_rate": "2.5 percent", "effective_date": "May 1, 2026", "expiration_date": "April 30, 2027"}}]}, {"pair_id": "conflict_75349958bdbc8c8c08ca349b", "claim_ids": ["claim_596a58c6f7f3b13a69d9ce99", "claim_9039d913db542b25c47e6ea0"], "query_ids": ["q_311"], "claims": [{"claim_id": "claim_596a58c6f7f3b13a69d9ce99", "quote": "Proclamation 10984 also provides that automobile manufacturers are eligible for an import adjustment offset equal to 3.75 percent of the aggregate Manufacturer's Suggested Retail Price (MSRP) of all automobiles assembled in the United States by that manufacturer, as determined annually by Commerce, from April 5, 2025, through April 30, 2030.", "url": "https://www.federalregister.gov/documents/2026/05/15/2026-09782/amending-the-procedures-to-administer-import-adjustment-offset-amounts-for-certain-imports-of", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"company": "automobile manufacturers", "tariff_program": "Proclamation 10984", "duty_rate": "3.75 percent", "effective_date": "April 5, 2025", "expiration_date": "April 30, 2030"}}, {"claim_id": "claim_9039d913db542b25c47e6ea0", "quote": "The automobile manufacturer may apply for an import adjustment offset amount equal to 2.5 percent of the aggregate MSRP value of all automobiles assembled in the United States from May 1, 2026, through April 30, 2027.", "url": "https://www.whitehouse.gov/presidential-actions/2025/04/amendments-to-adjusting-imports-of-automobiles-and-automobile-parts-into-the-united-states", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"duty_rate": "2.5 percent", "effective_date": "May 1, 2026", "expiration_date": "April 30, 2027"}}]}]}

